package org.apache.commons.math3.geometry.euclidean.twod;

import org.apache.commons.math3.geometry.partitioning.BSPTree;
import org.apache.commons.math3.geometry.partitioning.Region;
import org.apache.commons.math3.geometry.partitioning.SubHyperplane;
import org.apache.commons.math3.geometry.partitioning.AbstractSubHyperplane;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.oned.Euclidean1D;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.ArrayList;
import java.util.List;

public class AgentBRT_Math_32_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a BSPTree representing a polygon with a negative area
        // This should trigger the bug where the polygon is incorrectly considered infinite
        List<SubHyperplane<Euclidean2D>> boundary = new ArrayList<>();
        boundary.add(new AbstractSubHyperplane<Euclidean2D, Euclidean1D>(null, null) {
            @Override
            public double getSize() {
                return -1.0; // Simulate a negative area
            }

            @Override
            protected AbstractSubHyperplane<Euclidean2D, Euclidean1D> buildNew(BSPTree<Euclidean1D> tree, IntervalsSet remainingRegion) {
                return this;
            }

            @Override
            public boolean isEmpty() {
                return false;
            }
        });

        PolygonsSet polygon = new PolygonsSet(boundary);

        // Compute geometrical properties
        polygon.computeGeometricalProperties();

        // The expected size should not be infinite
        assertFalse(Double.isInfinite(polygon.getSize()));

        // The expected barycenter should not be NaN
        Vector2D actualBarycenter = (Vector2D) polygon.getBarycenter();
        assertFalse(Double.isNaN(actualBarycenter.getX()));
        assertFalse(Double.isNaN(actualBarycenter.getY()));
    }
}

