package org.apache.commons.math3.geometry.euclidean.twod;

import org.apache.commons.math3.geometry.partitioning.BSPTree;
import org.apache.commons.math3.geometry.partitioning.Region;
import org.apache.commons.math3.geometry.euclidean.twod.Vector2D;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_32_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a BSPTree representing a simple square polygon
        Vector2D[] loop = new Vector2D[] {
            new Vector2D(0, 0),
            new Vector2D(1, 0),
            new Vector2D(1, 1),
            new Vector2D(0, 1)
        };
        Vector2D[][] vertices = new Vector2D[][] { loop };

        // Create a PolygonsSet with these vertices
        PolygonsSet polygon = new PolygonsSet(vertices);

        // Compute geometrical properties
        polygon.computeGeometricalProperties();

        // The expected size of the square is 1 (area = 1*1)
        assertEquals(1.0, polygon.getSize(), 1e-10);

        // The expected barycenter of the square is at (0.5, 0.5)
        Vector2D expectedBarycenter = new Vector2D(0.5, 0.5);
        assertEquals(expectedBarycenter.getX(), polygon.getBarycenter().getX(), 1e-10);
        assertEquals(expectedBarycenter.getY(), polygon.getBarycenter().getY(), 1e-10);
    }
}

